// TH15 v1.00b Stage 2 midboss wave: blue Phantom01B, 3 rounds x 9 mirrored pairs.
// Source: st02.ecl.txt MainSub02 973-992 (entry), Phantom01 1176-1194,
// Phantom01B 1196-1203, Phantom01_at 1214-1234.  Death callback 1318-1347 not run
// (invincible shell, no player DPS) per task.
const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;
// Source type 7 (TH15 mapping): base radius 4, color 2.
const TH15_RING_BALL2: int = 464;

// Source MainSub02 976-992: %A=0; wait(2); three rounds of nine columns,
// each column spawns +A then mirrored -A, 30 frames apart.
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(2);
    for round in 0..3 {
        for col in 0..9 {
            var ax: fx = ((col + 1) * 16) as fx;
            _ = spawn_enemy(ax, -24fx, 100, 0, 1000, 0, phantom(ax));
            _ = spawn_enemy(0fx - ax, -24fx, 100, 0, 1000, 0, phantom(0fx - ax));
            wait(30);
        }
    }
}

// Source Phantom01_at 1216-1232: one emitter, aim mode 0, one lane,
// count layer = diffI(1,1,2,3); speed field1 = 1/2/3/4, field2 = 1/0.8/1/1.
// Each wave re-reads the player angle once and fires one bullet per layer.
async sub phantom_shoot() {
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var s0: fx = 1fx;
    var s1: fx = 1fx;
    var shots: int = 1;
    if rank == 1 {
        layers = 2; s0 = 2fx; s1 = 0.8fx;
    } else if rank == 2 {
        layers = 4; s0 = 3fx; s1 = 1fx; shots = 2;
    } else if rank >= 3 {
        layers = 8; s0 = 4fx; s1 = 1fx; shots = 3;
    }
    for n in 0..shots {
        // Source: wait(20 + ($RAND % 200)) before etOn.
        wait(20 + rand(200));
        var aim: angle = aim_player();
        for q in 0..layers {
            var v: fx = s0;
            if layers > 1 {
                v = s0 + (s1 - s0) * (q as fx) / ((layers - 1) as fx);
            }
            _ = fire(TH15_RING_BALL2, 2, $self_x, $self_y, v, aim, none, none);
        }
    }
}

// Source Phantom01 1178-1192.  Frames/motion:
//  moveVel(pi/2, 0.5) then moveVelTime(120, mode3, pi/2, 1.0): ABS descends,
//  speed 0.5 -> 1.0 with mode3 (quart-in), first step on the next tick.
//  moveEllipseRel(%F0=0, 2deg, r10, d0, beta=ABS_ANGLE=90deg, s0): REL layer
//  adds x = 10*cos(theta), theta = 0,2deg,... ; the setter frame is theta=0.
// Source flagSet(12)/flagClear(12) (offscreen-skip for 60 frames) has no target
// opcode; the target recycles only beyond +/-224px margin, so it is inert here.
async sub phantom(x0: fx) {
    set_invuln(65535);
    set_hurtbox(14fx);   // source setHurtbox(28,28) -> radius 14
    set_hitbox(8fx);     // source setHitbox(16,16) -> radius 8
    // Setter frame: REL center (0,0), theta=0 -> x offset +10 on top of ABS.
    move_to(0, x0 + 10fx, -24fx, EASE_LINEAR);
    spawn phantom_shoot();
    var th: angle = 0deg;
    var k: int = 0;
    var y: fx = -24fx;
    loop {
        k = k + 1;
        th = th + 2deg;
        var spd: fx = 1fx;
        if k <= 120 {
            var u: fx = (k as fx) / 120fx;
            spd = 0.5fx + 0.5fx * u * u * u * u;
        }
        var ny: fx = y + spd;
        var nx: fx = x0 + 10fx * cos(th);
        // Schedule next source tick's displacement; phase 5 integrates it.
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        y = ny;
        wait(1);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
